create or replace function duuk_private.crm_history() returns trigger language plpgsql security definer set search_path='' as $$ declare cid uuid; a uuid:=auth.uid(); begin
 if TG_TABLE_NAME='duuk_clients' then cid=new.id; else cid=new.client_id; end if;
 insert into public.duuk_client_history(client_id,actor_id,actor_name,action,details) values(cid,a,coalesce((select name from public.duuk_profiles where id=a),'Equipe DUUK'),case when TG_TABLE_NAME='duuk_clients' then case when TG_OP='INSERT' then 'Cliente criado' when to_jsonb(old)->>'stage' is distinct from to_jsonb(new)->>'stage' then 'Etapa alterada' else 'Cadastro atualizado' end when TG_TABLE_NAME='duuk_activities' then 'Contato registrado' else case when to_jsonb(new)->>'completed_at' is not null then 'Follow-up concluído' else 'Follow-up agendado' end end,case when TG_TABLE_NAME='duuk_clients' then jsonb_build_object('stage',to_jsonb(new)->>'stage','previous_stage',case when TG_OP='UPDATE' then to_jsonb(old)->>'stage' end) else jsonb_strip_nulls(jsonb_build_object('notes',to_jsonb(new)->>'notes','result',to_jsonb(new)->>'result','channel',to_jsonb(new)->>'channel')) end);
 if TG_TABLE_NAME='duuk_activities' then update public.duuk_clients set last_contact=greatest(coalesce(last_contact,new.occurred_at),new.occurred_at), first_contact=coalesce(first_contact,(new.occurred_at at time zone 'America/Sao_Paulo')::date) where id=cid; end if;
 return new;
end; $$;
